solution.solution.js:
const round2 = x => Math.round(x * 100) / 100;

function letterGrade(average) {
  if (average >= 90) return "A";
  if (average >= 80) return "B";
  if (average >= 70) return "C";
  if (average >= 60) return "D";
  return "F";
}

function clean(records) {
  return records
    .filter(({ student, subject, score }) =>
      typeof student === "string" && student.trim() !== "" &&
      typeof subject === "string" && subject.trim() !== "" &&
      typeof score === "number" && score >= 0 && score <= 100)
    .map(({ student, subject, score }) => ({
      student: student.trim(),
      subject: subject.trim().toLowerCase(),
      score,
    }));
}

const mean = values => values.reduce((a, b) => a + b, 0) / values.length;

function gradebook(records) {
  const rows = clean(records);

  const byStudent = new Map();
  for (const { student, subject, score } of rows) {
    if (!byStudent.has(student)) byStudent.set(student, new Map());
    byStudent.get(student).set(subject, score);
  }

  const students = [...byStudent].map(([name, scores]) => {
    const avg = mean([...scores.values()]);
    return { name, average: round2(avg), grade: letterGrade(avg), subjects: Object.fromEntries(scores) };
  });
  students.sort((a, b) => b.average - a.average || a.name.localeCompare(b.name));

  const bySubject = new Map();
  for (const { subject } of rows) {
    if (!bySubject.has(subject)) bySubject.set(subject, []);
  }
  for (const [name, scores] of byStudent) {
    for (const [subject, score] of scores) bySubject.get(subject).push({ name, score });
  }

  const subjects = {};
  for (const [subject, entries] of bySubject) {
    const best = [...entries].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))[0];
    subjects[subject] = { average: round2(mean(entries.map(e => e.score))), best: best.name };
  }

  return { students, subjects, top: students.length ? students[0].name : null };
}

unitTests:
const sample = () => [
  { student: "Ada", subject: "maths", score: 92 },
  { student: "Bob", subject: "maths", score: 61 },
  { student: "Ada", subject: "art", score: 78 },
  { student: "Bob", subject: "art", score: 85 },
  { student: "Cy", subject: "maths", score: 47 },
];

test("the example report", () => {
  checkEq(gradebook(sample()), {
    students: [
      { name: "Ada", average: 85, grade: "B", subjects: { maths: 92, art: 78 } },
      { name: "Bob", average: 73, grade: "C", subjects: { maths: 61, art: 85 } },
      { name: "Cy", average: 47, grade: "F", subjects: { maths: 47 } },
    ],
    subjects: { maths: { average: 66.67, best: "Ada" }, art: { average: 81.5, best: "Bob" } },
    top: "Ada",
  });
});

test("bad records are skipped", () => {
  const report = gradebook([
    { student: "Ada", subject: "maths", score: 101 },
    { student: "", subject: "maths", score: 50 },
    { student: "Bob", subject: "  ", score: 50 },
    { student: "Cy", subject: "maths", score: "90" },
    { student: "Di", subject: "maths", score: -1 },
    { student: 7, subject: "maths", score: 70 },
    { student: " Ed ", subject: " Maths ", score: 0 },
  ]);
  checkEq(report.students, [{ name: "Ed", average: 0, grade: "F", subjects: { maths: 0 } }]);
  checkEq(report.subjects, { maths: { average: 0, best: "Ed" } });
});

test("last record wins and subjects ignore case", () => {
  const report = gradebook([
    { student: "Ada", subject: "Art", score: 40 },
    { student: "Ada", subject: "art", score: 95 },
  ]);
  checkEq(report.students[0].subjects, { art: 95 });
  checkEq(report.students[0].grade, "A");
});

test("ties sort by name", () => {
  const report = gradebook([
    { student: "Zed", subject: "pe", score: 80 },
    { student: "Amy", subject: "pe", score: 80 },
  ]);
  checkEq(report.students.map(s => s.name), ["Amy", "Zed"]);
  checkEq(report.subjects.pe.best, "Amy");
  checkEq(report.top, "Amy");
});

test("grades use the unrounded average", () => {
  const report = gradebook([
    { student: "Ada", subject: "a", score: 90 },
    { student: "Ada", subject: "b", score: 91 },
  ]);
  checkEq(report.students[0].average, 90.5);
  checkEq(report.students[0].grade, "A");
  const low = gradebook([
    { student: "Bo", subject: "a", score: 89.996 },
    { student: "Bo", subject: "b", score: 89.996 },
  ]);
  checkEq(low.students[0].average, 90);
  checkEq(low.students[0].grade, "B");
});

test("empty input and inputs unchanged", () => {
  checkEq(gradebook([]), { students: [], subjects: {}, top: null });
  const records = sample();
  const copy = JSON.stringify(records);
  gradebook(records);
  checkEq(JSON.stringify(records), copy);
});

